select t.primary_key, p.product_part_sign, p.model, t.stored_num, t.await_un_qualified, t.await_qualified, t.in_qualified, t.in_un_qualified, p.pcs, t.state, t.apply_details::BIGINT[], p.primary_key as productPartCode, t.in_storage_staff::BIGINT[], t.accrual_await_qualified, t.accrual_await_un_qualified, t1.contract_number, t1.business_code, t1.in_storage_type, t2.stock_init_state, t2.primary_key as stock, t2.bar_code_number, t.component_code, t.component_name, t2.shipping_space::BIGINT[] from ${inboundOrderDetailTableName} t left join ${productPartTableName} p on t.product_or_part = p.primary_key left join ${inboundOrderTableName} t1 on t1.primary_key = t.inbound_order left join ${stockTableName} t2 on t2.product_part_code = p.primary_key where t.enterprise_code = #{enterpriseCode} and t.inbound_order = #{requestData.inboundOrderCode} and t.delete_flag = false
and ${dynamicTableNameProxy.getXiHangPartQuery("t.product_or_part","xihang",requestData.partUnityNo)}
AND (p.model like '%'|| #{requestData.searchName} ||'%' or p.product_part_sign like '%'|| #{requestData.searchName} ||'%')
and t2.bar_code_number LIKE '%'|| #{requestData.barCodeNumber} ||'%'
and t.state in
#{code}
${dataScopeParams.dataScope}
order by t.create_time desc,t.id desc

