SELECT SUM(inboundOrderDetail.in_qualified)
FROM ${inboundOrderTableName} inboundOrder
         LEFT JOIN ${inboundOrderDetailTableName} inboundOrderDetail
                   ON inboundOrder.primary_key = inboundOrderDetail.inbound_order
WHERE inboundOrder.in_storage_type = #{inStorageType}
  AND inboundOrder.delete_flag = 'f'
  AND inboundOrderDetail.delete_flag = 'f'
  AND inboundOrder.enterprise_code = #{enterpriseCode}
  AND inboundOrderDetail.enterprise_code = #{enterpriseCode}
  AND inboundOrderDetail.product_or_part = #{materialCode}

